    console.log("[超能伙伴性能]", {
      ...counters,
      emitMs: Math.round(counters.emitMs),
      diagnosticFlushMs: Math.round(counters.diagnosticFlushMs),
      loopP99Ms: loop ? Math.round(loop.percentile(99) / 1e6) : 0,
      loopMaxMs: loop ? Math.round(loop.max / 1e6) : 0
    });
