var botPerf = {
  enabled,
  count(key, value = 1) {
    if (enabled) counters[key] += value;
  },
  time(key, fn) {
    if (!enabled) return fn();
    const start = performance.now();
    try {
      return fn();
    } finally {
      counters[key] += performance.now() - start;
    }
  }
};
